#!/usr/bin/env python3
"""Lightweight structural validator for deckard .rpl scenario files."""
import re
import sys

import dns.rdata
import dns.rdataclass
import dns.rdatatype


def fail(path, lineno, msg):
    raise SystemExit(f"{path}:{lineno}: {msg}")


def main(path):
    lines = open(path, encoding="utf-8").read().splitlines()
    in_config = False
    scenario = False
    stack = []
    ranges = 0
    steps = 0
    section = None
    for idx, raw in enumerate(lines, start=1):
        line = raw.split(";", 1)[0].strip()
        if not line:
            continue
        if line == "CONFIG_END":
            if not in_config:
                fail(path, idx, "CONFIG_END without CONFIG block")
            in_config = False
            continue
        if not scenario and not in_config and not line.startswith(("SCENARIO_BEGIN",)):
            # config options before CONFIG_END are free-form
            if not stack:
                continue
        if line.startswith("SCENARIO_BEGIN"):
            scenario = True
            continue
        if line == "SCENARIO_END":
            if stack:
                fail(path, idx, f"unclosed blocks: {stack}")
            scenario = False
            continue
        if line.startswith("RANGE_BEGIN"):
            m = re.match(r"RANGE_BEGIN\s+(\d+)\s+(\d+)$", line)
            if not m:
                fail(path, idx, "bad RANGE_BEGIN header")
            if int(m.group(1)) > int(m.group(2)):
                fail(path, idx, "RANGE_BEGIN start > end")
            stack.append("RANGE")
            ranges += 1
            continue
        if line == "RANGE_END":
            if not stack or stack[-1] != "RANGE":
                fail(path, idx, "RANGE_END without RANGE_BEGIN")
            stack.pop()
            continue
        if line == "ENTRY_BEGIN":
            if "ENTRY" in stack:
                fail(path, idx, "nested ENTRY_BEGIN")
            stack.append("ENTRY")
            section = None
            continue
        if line == "ENTRY_END":
            if not stack or stack[-1] != "ENTRY":
                fail(path, idx, "ENTRY_END without ENTRY_BEGIN")
            stack.pop()
            section = None
            continue
        if re.match(r"STEP\s+\d+\s+(QUERY|CHECK_ANSWER|CHECK_OUT)$", line):
            steps += 1
            continue
        if line.startswith("SECTION "):
            name = line.split()[1]
            if name not in ("QUESTION", "ANSWER", "AUTHORITY", "ADDITIONAL"):
                fail(path, idx, f"unknown section {name}")
            section = name
            continue
        if line.startswith(("MATCH ", "ADJUST ", "REPLY ", "ADDRESS ")):
            continue
        # Otherwise it should be a DNS record inside a section.
        if section is not None and "ENTRY" in stack:
            parts = line.split()
            if len(parts) < 4:
                fail(path, idx, f"malformed record: {line}")
            try:
                rtype = dns.rdatatype.from_text(parts[-2])
                rclass = dns.rdataclass.from_text(parts[-3])
            except Exception as exc:  # noqa: BLE001
                fail(path, idx, f"bad record class/type ({exc}): {line}")
            rdata_text = " ".join(parts[-1:])
            try:
                dns.rdata.from_text(rclass, rtype, rdata_text)
            except Exception as exc:  # noqa: BLE001
                fail(path, idx, f"bad rdata ({exc}): {line}")
            continue
        fail(path, idx, f"unrecognized line: {line}")

    if scenario:
        fail(path, len(lines), "missing SCENARIO_END")
    print(f"{path}: OK ({ranges} ranges, {steps} steps)")


if __name__ == "__main__":
    main(sys.argv[1])

