import re, sys
import dns.rdata, dns.rdataclass, dns.rdatatype
def fail(p,n,m): raise SystemExit(f"{p}:{n}: {m}")
path=sys.argv[1]
lines=open(path,encoding="utf-8").read().splitlines()
in_config=False; scenario=False; stack=[]; ranges=steps=0; section=None
for idx,raw in enumerate(lines,1):
    line=raw.split(";",1)[0].strip()
    if not line: continue
    if not scenario and not stack and not in_config and line!="CONFIG_END" and not line.startswith("SCENARIO_BEGIN"):
        in_config=True
    if line=="CONFIG_END":
        if not in_config: fail(path,idx,"CONFIG_END without CONFIG block")
        in_config=False; continue
    if in_config: continue
    if line.startswith("SCENARIO_BEGIN"): scenario=True; continue
    if line=="SCENARIO_END":
        if stack: fail(path,idx,f"unclosed {stack}")
        scenario=False; continue
    if line.startswith("RANGE_BEGIN"):
        m=re.match(r"RANGE_BEGIN\s+(\d+)\s+(\d+)$",line)
        if not m or int(m.group(1))>int(m.group(2)): fail(path,idx,"bad RANGE_BEGIN")
        stack.append("RANGE"); ranges+=1; continue
    if line=="RANGE_END":
        if not stack or stack[-1]!="RANGE": fail(path,idx,"RANGE_END mismatch")
        stack.pop(); continue
    if line=="ENTRY_BEGIN":
        if "ENTRY" in stack: fail(path,idx,"nested ENTRY")
        stack.append("ENTRY"); section=None; continue
    if line=="ENTRY_END":
        if not stack or stack[-1]!="ENTRY": fail(path,idx,"ENTRY_END mismatch")
        stack.pop(); section=None; continue
    if re.match(r"STEP\s+\d+\s+(QUERY|CHECK_ANSWER|CHECK_OUT)$",line): steps+=1; continue
    if line.startswith("SECTION "):
        name=line.split()[1]
        if name not in ("QUESTION","ANSWER","AUTHORITY","ADDITIONAL"): fail(path,idx,f"bad section {name}")
        section=name; continue
    if line.startswith(("MATCH ","ADJUST ","REPLY ","ADDRESS ")): continue
    if section is not None and "ENTRY" in stack:
        if section=="QUESTION":
            m=re.match(r"(\S+)\s+(?:(IN|CH|HS)\s+)?([A-Z0-9]+)$",line)
            if not m: fail(path,idx,f"bad question record: {line}")
            dns.rdatatype.from_text(m.group(3)); continue
        m=re.match(r"(\S+)\s+(?:(\d+)\s+)?(?:(IN|CH|HS)\s+)?([A-Z0-9]+)\s+(.*)$",line)
        if not m: fail(path,idx,f"bad record: {line}")
        rc=dns.rdataclass.from_text(m.group(3) or "IN"); rt=dns.rdatatype.from_text(m.group(4))
        try: dns.rdata.from_text(rc,rt,m.group(5))
        except Exception as e: fail(path,idx,f"bad rdata ({e}): {line}")
        continue
    fail(path,idx,f"unrecognized: {line}")
if scenario: fail(path,len(lines),"missing SCENARIO_END")
print(f"{path}: OK ({ranges} ranges, {steps} steps)")

